var n=`1346-fricase-paceno`;var a=`world-1346`;var t=`BO`;var o=`south-america`;var s=4;var r=166;var g={en:`Fricasé Paceño`,ua:`Фрікассе по-ла-паськи`};var d={en:`Fricasé Paceño is a dish from Bolivia featuring pork shoulder, aji amarillo paste, garlic, yellow onion. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Фрікассе по-ла-паськи, страва кухні країни Болівія з такими основними складниками: свиняча лопатка, паста ахі амарильйо, часник, жовта цибуля. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var l=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 55 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 55 хвилин.`,t:[`marinating`],m:55,i:[[`pork-shoulder`,780,`g`],[`aji-amarillo-paste`,60,`g`],[`garlic`,5,`clove`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 12 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 12 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:12,i:[[`yellow-onion`,180,`g`],[`canola-oil`,45,`ml`],[`ground-cumin`,6,`g`]]},{en:`Add the braising liquid and seasonings, cover and cook gently for about 95 minutes until the meat is tender and safely cooked.`,ua:`Додайте рідину та приправи для тушкування, накрийте кришкою й готуйте на малому вогні приблизно 95 хвилин до м’якості та повної готовності м’яса.`,t:[`braising`],m:95,i:[[`chicken-stock`,1050,`ml`],[`dried-oregano`,6,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`ground-black-pepper`,4,`g`],[`green-onion`,25,`g`]]}];var c={slug:n,id:a,country:`BO`,region:o,servings:4,minutes:166,title:g,text:d,steps:l};export{t as country,c as default,a as id,r as minutes,o as region,s as servings,n as slug,l as steps,d as text,g as title};